// Normalize and validate input
const body = $input.item.json;

// If nested under body key (some proxy/forwarding patterns), unwrap
const payload = body.body || body;

// Validate required fields
if (!payload.text || typeof payload.text !== 'string') {
  throw new Error('Missing or invalid text field');
}

const text = payload.text.trim();

// Check length constraints
const minLength = parseInt($env.MIN_TEXT_LENGTH || '10');
const maxLength = parseInt($env.MAX_TEXT_LENGTH || '50000');

if (text.length < minLength) {
  throw new Error(`Text too short (min ${minLength} characters)`);
}

if (text.length > maxLength) {
  throw new Error(`Text too long (max ${maxLength} characters)`);
}

// Generate document_id if not provided
const document_id = payload.document_id || `doc_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;

// Compute text hash (SHA-256)
const crypto = require('crypto');
const normalized_text = text.replace(/\s+/g, ' ').trim();
const text_hash = crypto.createHash('sha256').update(normalized_text).digest('hex');

return [{ json: {
  document_id,
  text,
  text_hash,
  source_url: payload.source_url || null,
  content_type: payload.content_type || null,
  metadata: payload.metadata || {},
  original_file: payload.original_file || null,
  requested_by: payload.requested_by || null,
  timestamp: new Date().toISOString()
} }];

// Return cached result
const cached = $input.item.json.result;

// Add warning message
cached.warning = "Human-likely means no strong AI-generation signal was detected; it does not prove human authorship.";
cached.cached = true;

return [{ json: cached }];

// Build result from verified provenance
const input = $('Normalize Input').item.json;
const provenance = $input.item.json;
const config = $('Config from Env').item.json;

return [{ json: {
  document_id: input.document_id,
  classification: 'AI_GENERATED',
  ai_probability: 1.0,
  confidence: 1.0,
  method: 'VERIFIED_PROVENANCE',
  review_required: false,
  evidence: {
    provenance: provenance,
    watermark: {},
    statistics: {},
    models: []
  },
  versions: {
    detector: config.detector_version,
    features: config.feature_schema_version,
    classifier: config.classifier_version,
    thresholds: config.threshold_version
  }
} }];

// Build result from watermark detection
const input = $('Normalize Input').item.json;
const watermark = $input.item.json;
const config = $('Config from Env').item.json;

return [{ json: {
  document_id: input.document_id,
  classification: 'AI_GENERATED',
  ai_probability: watermark.score || 0.95,
  confidence: watermark.confidence || 0.9,
  method: 'WATERMARK_DETECTED',
  review_required: false,
  evidence: {
    provenance: {},
    watermark: watermark,
    statistics: {},
    models: []
  },
  versions: {
    detector: config.detector_version,
    features: config.feature_schema_version,
    classifier: config.classifier_version,
    thresholds: config.threshold_version
  }
} }];

