// Parse and validate model responses
const features = $('Extract Statistical Features').item.json;
const primary_raw = $('Primary Model Classification').item.json;
const secondary_raw = $('Secondary Model Classification').item.json;

// Parse primary response
let primary_result;
try {
  const primary_content = primary_raw.choices[0].message.content;
  primary_result = typeof primary_content === 'string' ? JSON.parse(primary_content) : primary_content;
} catch (e) {
  throw new Error('Failed to parse primary model response: ' + e.message);
}

// Validate primary
if (!primary_result.ai_probability || primary_result.ai_probability < 0 || primary_result.ai_probability > 1) {
  throw new Error('Invalid primary ai_probability');
}
if (!primary_result.confidence || primary_result.confidence < 0 || primary_result.confidence > 1) {
  throw new Error('Invalid primary confidence');
}

// Parse secondary response
let secondary_result;
try {
  const secondary_content = secondary_raw.choices[0].message.content;
  secondary_result = typeof secondary_content === 'string' ? JSON.parse(secondary_content) : secondary_content;
} catch (e) {
  throw new Error('Failed to parse secondary model response: ' + e.message);
}

// Validate secondary
if (!secondary_result.ai_probability || secondary_result.ai_probability < 0 || secondary_result.ai_probability > 1) {
  throw new Error('Invalid secondary ai_probability');
}
if (!secondary_result.confidence || secondary_result.confidence < 0 || secondary_result.confidence > 1) {
  throw new Error('Invalid secondary confidence');
}

return [{ json: {
  statistical_probability: features.statistical_probability,
  features: features.features,
  primary_model_result: primary_result,
  secondary_model_result: secondary_result
} }];

// Build final result object
const input = $('Normalize Input').item.json;
const features = $('Extract Statistical Features').item.json;
const ensemble = $input.item.json;
const provenance = $('Provenance Check').item.json;
const watermark = $('Watermark Detection').item.json;
const primary_raw = $('Primary Model Classification').item.json;
const secondary_raw = $('Secondary Model Classification').item.json;
const config = $('Config from Env').item.json;

return [{ json: {
  document_id: input.document_id,
  classification: ensemble.classification,
  ai_probability: ensemble.ai_probability,
  confidence: ensemble.confidence,
  method: ensemble.method,
  review_required: ensemble.review_required,

  evidence: {
    provenance: provenance.found ? provenance : {},
    watermark: watermark.detected ? watermark : {},
    statistics: features.features,
    models: [
      {
        provider: 'primary',
        model: config.primary_model,
        result: ensemble.component_scores
      },
      {
        provider: 'secondary',
        model: config.secondary_model,
        result: ensemble.component_scores
      }
    ]
  },

  warning: "Human-likely means no strong AI-generation signal was detected; it does not prove human authorship.",

  versions: {
    detector: config.detector_version,
    features: config.feature_schema_version,
    classifier: config.classifier_version,
    thresholds: config.threshold_version
  },

  _internal: {
    text_hash: input.text_hash,
    timestamp: input.timestamp
  }
} }];
